content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --danger-color: #f87171;
    --danger-hover: #ef4444;
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.5), 0 2px 4px -2px rgb(0 0 0 / 0.5);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

/* スクロールバーのスタイリング */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-color);
}

::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 2px solid var(--border-color);
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-color);
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

@media (max-width: 480px) {
  .app-container {
    padding: 12px 8px;
    gap: 16px;
  }
  .title {
    font-size: 1.4rem;
  }
}

@media (max-width: 768px) {
  .main-content {
    grid-template-columns: 1fr;
  }
  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }
}

@media (min-width: 1280px) {
  .app-container {
    max-width: 1320px;
  }
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.chart-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  min-height: 300px;
}

.list-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.detail-box {
  background-color: color-mix(in srgb, var(--primary-color) 10%, var(--card-bg));
  border-radius: 8px;
  padding: 16px;
  margin-top: 16px;
  border-left: 4px solid var(--primary-color);
}

.form-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.input-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.input-group input,
.input-group select {
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background-color: var(--card-bg);
  color: var(--text-main);
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

.input-group input:focus,
.input-group select:focus {
  border-color: var(--primary-color);
}

.btn {
  padding: 10px 16px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  border: none;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-danger {
  background-color: var(--danger-color);
  color: white;
  padding: 6px 12px;
  font-size: 0.875rem;
}

.btn-danger:hover {
  background-color: var(--danger-hover);
}

.expense-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 350px;
  overflow-y: auto;
  padding-right: 4px;
}

.expense-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background-color: color-mix(in srgb, var(--border-color) 30%, var(--card-bg));
  border-radius: 8px;
  border: 1px solid var(--border-color);
  transition: box-shadow 0.2s;
}

.expense-item:hover {
  box-shadow: 0 2px 4px rgb(0 0 0 / 0.05);
}

.total-display {
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background-color: color-mix(in srgb, var(--primary-color) 15%, var(--card-bg));
  border-radius: 8px;
  color: var(--primary-color);
}

export type Category = '食費' | '住居費' | '娯楽' | '交通費' | '通信費' | 'その他';

export interface ExpenseItem {
  id: string;
  category: Category;
  amount: number;
  memo: string;
  date: string;
}

export interface ExpenseFormData {
  category: Category;
  amount: number;
  memo: string;
  date: string;
}

export interface ChartDataPoint {
  name: string;
  value: number;
  color: string;
}

import { useMemo } from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { ExpenseItem, ChartDataPoint } from '../types';

interface ExpenseChartProps {
  expenses: ExpenseItem[];
  onSelectCategory?: (category: string) => void;
  selectedCategory?: string | null;
}

const COLORS = ['#4f46e5', '#3b82f6', '#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

export default function ExpenseChart({ expenses = [], onSelectCategory, selectedCategory }: ExpenseChartProps) {
  const categoryMap = useMemo(() => {
    return expenses.reduce((acc, item) => {
      acc[item.category] = (acc[item.category] || 0) + item.amount;
      return acc;
    }, {} as Record<string, number>);
  }, [expenses]);

  const data: ChartDataPoint[] = useMemo(() => {
    return Object.keys(categoryMap).map((cat, index) => ({
      name: cat,
      value: categoryMap[cat],
      color: COLORS[index % COLORS.length]
    }));
  }, [categoryMap]);

  const handlePieClick = (entry: ChartDataPoint) => {
    if (onSelectCategory) {
      onSelectCategory(entry.name);
    }
  };

  const selectedData = selectedCategory ? categoryMap[selectedCategory] : null;

  return (
    <div className="chart-section" style={{ width: '100%' }}>
      {data.length === 0 ? (
        <p style={{ color: 'var(--text-muted)' }}>データがありません</p>
      ) : (
        <div style={{ width: '100%', height: 260 }}>
          <ResponsiveContainer>
            <PieChart>
              <Pie
                data={data}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={90}
                paddingAngle={4}
                dataKey="value"
                onClick={(entry: ChartDataPoint) => handlePieClick(entry)}
                cursor="pointer"
              >
                {data.map((entry, index) => (
                  <Cell 
                    key={`cell-${index}`} 
                    fill={entry.color} 
                    stroke={selectedCategory === entry.name ? '#1e293b' : 'none'}
                    strokeWidth={selectedCategory === entry.name ? 2 : 0}
                  />
                ))}
              </Pie>
              <Tooltip formatter={(value: number) => [`¥${value.toLocaleString()}`, '金額']} />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>
      )}

      {selectedCategory && (
        <div className="detail-box" style={{ width: '100%' }}>
          <strong>選択中: {selectedCategory}</strong>
          <p>合計金額: ¥{(selectedData || 0).toLocaleString()}</p>
          <p style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>円グラフの項目をクリックすると内訳フィルタが切り替わります</p>
        </div>
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { ExpenseItem, Category } from './types';
import ExpenseChart from './components/ExpenseChart';
import './index.css';

const getInitialExpenses = (): ExpenseItem[] => {
  const today = new Date();
  const year = today.getFullYear();
  const month = String(today.getMonth() + 1).padStart(2, '0');
  return [
    { id: crypto.randomUUID(), category: '食費', amount: 25000, memo: 'スーパーでのまとめ買い', date: `${year}-${month}-01` },
    { id: crypto.randomUUID(), category: '住居費', amount: 80000, memo: '家賃', date: `${year}-${month}-02` },
    { id: crypto.randomUUID(), category: '娯楽', amount: 8500, memo: '映画とカフェ', date: `${year}-${month}-05` },
    { id: crypto.randomUUID(), category: '交通費', amount: 5000, memo: '定期券更新', date: `${year}-${month}-10` },
    { id: crypto.randomUUID(), category: '食費', amount: 3200, memo: '外食ランチ', date: `${year}-${month}-12` },
  ];
};

export default function App() {
  const [expenses, setExpenses] = useState<ExpenseItem[]>(getInitialExpenses);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  const [category, setCategory] = useState<Category>('食費');
  const [amount, setAmount] = useState('');
  const [memo, setMemo] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleAddExpense = (e: React.FormEvent) => {
    e.preventDefault();
    const numAmount = Number(amount);
    if (!numAmount || numAmount <= 0) return;

    const newItem: ExpenseItem = {
      id: crypto.randomUUID(),
      category,
      amount: numAmount,
      memo: memo || '無題',
      date,
    };

    setExpenses([newItem, ...expenses]);
    setAmount('');
    setMemo('');
  };

  const handleDeleteExpense = (id: string) => {
    setExpenses(expenses.filter(item => item.id !== id));
  };

  const totalAmount = useMemo(() => {
    return expenses.reduce((sum, item) => sum + item.amount, 0);
  }, [expenses]);

  const filteredExpenses = useMemo(() => {
    return selectedCategory
      ? expenses.filter(item => item.category === selectedCategory)
      : expenses;
  }, [expenses, selectedCategory]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">家計簿ダッシュボード</h1>
        <div style={{ color: 'var(--text-muted)' }}>支出内訳の確認と管理</div>
      </header>

      <main className="main-content">
        <div className="card">
          <h2>支出内訳グラフ</h2>
          <ExpenseChart 
            expenses={expenses} 
            selectedCategory={selectedCategory}
            onSelectCategory={(cat) => setSelectedCategory(selectedCategory === cat ? null : cat)}
          />
        </div>

        <div className="card list-section">
          <h2>支出の追加</h2>
          <form className="form-section" onSubmit={handleAddExpense}>
            <div className="input-group">
              <label>カテゴリ</label>
              <select value={category} onChange={(e) => setCategory(e.target.value as Category)}>
                <option value="食費">食費</option>
                <option value="住居費">住居費</option>
                <option value="娯楽">娯楽</option>
                <option value="交通費">交通費</option>
                <option value="通信費">通信費</option>
                <option value="その他">その他</option>
              </select>
            </div>
            <div className="input-group">
              <label>金額 (円)</label>
              <input 
                type="number" 
                value={amount} 
                onChange={(e) => setAmount(e.target.value)} 
                placeholder="例: 1500" 
                required 
              />
            </div>
            <div className="input-group">
              <label>日付</label>
              <input 
                type="date" 
                value={date} 
                onChange={(e) => setDate(e.target.value)} 
                required 
              />
            </div>
            <div className="input-group">
              <label>メモ</label>
              <input 
                type="text" 
                value={memo} 
                onChange={(e) => setMemo(e.target.value)} 
                placeholder="例: ランチ代" 
              />
            </div>
            <button type="submit" className="btn btn-primary">追加する</button>
          </form>
        </div>
      </main>

      <div className="card">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2>支出一覧 {selectedCategory && `(${selectedCategory}のみ表示)`}</h2>
          {selectedCategory && (
            <button className="btn" style={{ background: '#e2e8f0', fontSize: '0.875rem' }} onClick={() => setSelectedCategory(null)}>
              フィルター解除
            </button>
          )}
        </div>

        <div className="total-display">
          <span>合計支出</span>
          <span>¥{totalAmount.toLocaleString()}</span>
        </div>

        <ul className="expense-list">
          {filteredExpenses.length === 0 ? (
            <li style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px' }}>
              支出データがありません
            </li>
          ) : (
            filteredExpenses.map(item => (
              <li key={item.id} className="expense-item">
                <div>
                  <div style={{ fontWeight: '600' }}>{item.category} - ¥{item.amount.toLocaleString()}</div>
                  <div style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>{item.date} / {item.memo}</div>
                </div>
                <button className="btn btn-danger" onClick={() => handleDeleteExpense(item.id)}>削除</button>
              </li>
            ))
          )}
        </ul>
      </div>
    </div>
  );
}
